"""Promo codes: generated by admins, they add Premium days only on top of a paid subscription."""

from datetime import timedelta

import httpx
import pytest

from bot import promo
from bot.api.app import create_app
from bot.billing import Billing
from bot.db.repo import Repo
from bot.db.session import init_db, make_engine, make_sessionmaker
from bot.utils import utcnow
from tests.test_billing_api import FakeAI, FakeBot, auth, settings


@pytest.fixture
async def repo():
    engine = make_engine("sqlite+aiosqlite:///:memory:")
    await init_db(engine)
    async with make_sessionmaker(engine)() as session:
        yield Repo(session)
    await engine.dispose()


async def test_code_waits_for_payment_then_adds_days(repo):
    now = utcnow()
    user, _ = await repo.ensure_user(7, native_lang="ru", timezone="Asia/Tashkent", target_lang="en")
    billing = Billing(repo.s, settings())
    created = await promo.create(repo.s, now, days=30, max_uses=0)
    assert promo.looks_like_code(created.code) and created.code.startswith("RIMY-")

    # no Premium bought yet: the code is accepted but waits
    result = await promo.redeem(repo.s, user, created.code.lower(), now)  # case doesn't matter
    assert result.status == "pending" and not user.is_premium(now)
    assert await promo.pending_days(repo.s, user) == 30
    assert (await promo.redeem(repo.s, user, created.code, now)).status == "already"

    # the payment applies it: 30 paid days + 30 promo days
    until = await billing.grant_premium(user, now, "charge-1", 123, "premium_30d")
    assert until - now == timedelta(days=60)
    assert await promo.pending_days(repo.s, user) == 0

    # a second code for someone who has already paid is applied at once
    second = await promo.create(repo.s, now, days=7, max_uses=1, code="stand-7")
    assert (await promo.redeem(repo.s, user, "STAND-7", now)).status == "applied"
    assert user.premium_until - now == timedelta(days=67)

    other, _ = await repo.ensure_user(8, native_lang="ru", timezone="Asia/Tashkent", target_lang="en")
    assert (await promo.redeem(repo.s, other, "STAND-7", now)).status == "exhausted"  # max_uses=1
    await promo.set_active(repo.s, second.id, False)
    assert (await promo.redeem(repo.s, other, "STAND-7", now)).status == "inactive"
    assert (await promo.redeem(repo.s, other, "NOPE-123", now)).status == "unknown"

    with pytest.raises(ValueError):
        await promo.create(repo.s, now, days=7, max_uses=0, code="stand-7")  # duplicate
    rows = {row["code"]: row for row in await promo.overview(repo.s)}
    assert rows["STAND-7"]["used"] == 1 and rows["STAND-7"]["applied"] == 1 and not rows["STAND-7"]["active"]
    assert rows[created.code]["used"] == 1 and rows[created.code]["applied"] == 1


@pytest.fixture
async def client(tmp_path):
    url = f"sqlite+aiosqlite:///{(tmp_path / 'api.db').as_posix()}"
    engine = make_engine(url)
    await init_db(engine)
    app = create_app(settings(url), make_sessionmaker(engine), FakeAI(), FakeBot())
    async with httpx.AsyncClient(transport=httpx.ASGITransport(app=app), base_url="http://test") as c:
        yield c
    await engine.dispose()


async def test_promo_api(client):
    admin = auth(1)  # owner_id=1 in the test settings
    assert (await client.post("/api/admin/promos", json={"days": 30}, headers=auth(40))).status_code == 403
    assert (await client.get("/api/admin/promos", headers=auth(40))).status_code == 403

    code = (await client.post("/api/admin/promos", json={"days": 30, "max_uses": 50}, headers=admin)).json()["code"]
    assert (await client.post("/api/admin/promos", json={"days": 30, "code": code}, headers=admin)).status_code == 400

    redeemed = (await client.post("/api/promo", json={"code": code}, headers=auth(40))).json()
    assert redeemed["status"] == "pending" and redeemed["ok"] and "+30" in redeemed["message"]
    assert (await client.get("/api/me", headers=auth(40))).json()["promo_pending_days"] == 30
    assert (await client.post("/api/promo", json={"code": "WRONG-1"}, headers=auth(40))).json()["ok"] is False

    promos = (await client.get("/api/admin/promos", headers=admin)).json()["promos"]
    assert promos[0]["code"] == code and promos[0]["used"] == 1 and promos[0]["applied"] == 0
    assert (await client.post(f"/api/admin/promos/{promos[0]['id']}", json={"active": False}, headers=admin)).status_code == 200
    assert (await client.post("/api/promo", json={"code": code}, headers=auth(41))).json()["status"] == "inactive"

    funnel = {s["key"]: s["users"] for s in (await client.get("/api/admin/dashboard", headers=admin)).json()["funnel"]}
    assert funnel["promo_redeemed"] == 1
